<?php
require __DIR__ . '/mira-view-access.php';
require __DIR__.'/gallery-common.php';
if (empty($_SESSION['artwork_csrf'])) $_SESSION['artwork_csrf'] = bin2hex(random_bytes(32));
$token=$_SESSION['artwork_csrf'];
$uid=(int)$_SESSION['user_id'];
$id=filter_input(INPUT_GET,'id',FILTER_VALIDATE_INT);
$art=($id&&$id>0)?(miraApprovedArtworks($conn,'',(int)$id,1)[0]??null):null;
if (!$art) http_response_code(404);
$saved=false;$liked=false;$likes=0;$average=0;$ratingCount=0;$myRating=0;$comments=[];
if ($art) {
  $stmt=$conn->prepare('SELECT 1 FROM saved_artworks WHERE user_id=? AND artwork_id=? LIMIT 1');
  $stmt->bind_param('ii',$uid,$id);$stmt->execute();$saved=$stmt->get_result()->num_rows > 0;$stmt->close();
  $stmt=$conn->prepare('SELECT COUNT(*) AS total, COALESCE(MAX(CASE WHEN user_id=? THEN 1 ELSE 0 END),0) AS mine FROM artwork_likes WHERE artwork_id=?');
  $stmt->bind_param('ii',$uid,$id);$stmt->execute();$r=$stmt->get_result()->fetch_assoc();$likes=(int)$r['total'];$liked=(bool)$r['mine'];$stmt->close();
  $stmt=$conn->prepare('SELECT COALESCE(AVG(rating_value),0) AS average,COUNT(*) AS total, COALESCE(MAX(CASE WHEN user_id=? THEN rating_value END),0) AS mine FROM ratings WHERE artwork_id=?');
  $stmt->bind_param('ii',$uid,$id);$stmt->execute();$r=$stmt->get_result()->fetch_assoc();$average=(float)$r['average'];$ratingCount=(int)$r['total'];$myRating=(int)$r['mine'];$stmt->close();
  $stmt=$conn->prepare('SELECT c.comment_id,c.user_id,c.comment_text,c.created_at,u.FULL_NAME FROM comments c JOIN users u ON u.USER_ID=c.user_id WHERE c.artwork_id=? ORDER BY c.created_at DESC,c.comment_id DESC LIMIT 100');
  $stmt->bind_param('i',$id);$stmt->execute();$comments=$stmt->get_result()->fetch_all(MYSQLI_ASSOC);$stmt->close();
}
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?= $art?miraEsc($art['title']).' | MIRA':'Artwork Not Found | MIRA' ?></title><link rel="stylesheet" href="style.css"><link rel="stylesheet" href="gallery.css"><link rel="stylesheet" href="interactions.css"><script src="theme.js" defer></script><link rel="stylesheet" href="mira-student-nav.css?v=2"><link rel="stylesheet" href="mira-design-system.css?v=1">
</head><body class="user-home-page mira-gallery-page"><?php require __DIR__ . "/mira-student-nav.php"; ?><main class="mira-gallery-wrap">
<?php if (!$art): ?><div class="mira-empty"><h1>Artwork unavailable</h1><p>This artwork is not approved, or it no longer exists.</p></div>
<?php else: ?><section class="mira-artwork-detail"><div class="mira-detail-photo"><img src="<?= miraEsc(miraArtworkImage($art['image_path'])) ?>" alt="<?= miraEsc($art['title']) ?>"></div><div class="mira-detail-copy"><p class="mira-detail-label"><?= miraEsc($art['category_name']) ?></p><h1><?= miraEsc($art['title']) ?></h1><p class="mira-detail-artist">Created by <a href="artist-profile.php?id=<?= (int)$art['artist_id'] ?>"><?= miraEsc($art['artist_name']) ?></a></p><p class="mira-detail-desc"><?= nl2br(miraEsc($art['description']??'')) ?></p><p class="mira-detail-date">Shared <?= miraEsc(date('M j, Y',strtotime($art['created_at']))) ?></p>
<?php if (!$miraAdminPreview): ?><div class="mira-actions"><form method="post" action="artwork-interactions.php"><input type="hidden" name="csrf_token" value="<?= miraEsc($token) ?>"><input type="hidden" name="artwork_id" value="<?= (int)$id ?>"><input type="hidden" name="action" value="like"><button type="submit" class="mira-action-btn"><?= $liked?'♥ Unlike':'♡ Like' ?> (<?= $likes ?>)</button></form><form method="post" action="save-artwork.php"><input type="hidden" name="csrf_token" value="<?= miraEsc($token) ?>"><input type="hidden" name="artwork_id" value="<?= (int)$id ?>"><input type="hidden" name="action" value="<?= $saved?'remove':'save' ?>"><button type="submit" class="mira-action-btn"><?= $saved?'★ Remove from Saved':'☆ Save Artwork' ?></button></form><a class="mira-action-btn" href="artist-profile.php?id=<?= (int)$art['artist_id'] ?>">View artist / Follow →</a></div>
<div class="mira-rating-box"><h2>Rate this artwork</h2><p><?= $ratingCount?number_format($average,1).' / 5 from '.$ratingCount.' rating(s)':'No ratings yet' ?></p><form method="post" action="artwork-interactions.php"><input type="hidden" name="csrf_token" value="<?= miraEsc($token) ?>"><input type="hidden" name="artwork_id" value="<?= (int)$id ?>"><input type="hidden" name="action" value="rating"><label for="rating_value">Your rating</label><select id="rating_value" name="rating_value" required><?php for($i=1;$i<=5;$i++): ?><option value="<?= $i ?>" <?= $myRating===$i?'selected':'' ?>><?= $i ?> star<?= $i===1?'':'s' ?></option><?php endfor; ?></select><button type="submit" class="mira-action-btn">Save rating</button></form></div>
</div><?php endif; ?></section><section class="mira-comment-box mira-artwork-comments"><?php if (!$miraAdminPreview): ?><h2>Leave a comment</h2><form method="post" action="artwork-interactions.php"><input type="hidden" name="csrf_token" value="<?= miraEsc($token) ?>"><input type="hidden" name="artwork_id" value="<?= (int)$id ?>"><input type="hidden" name="action" value="comment"><label for="comment_text">Share your thoughts about this artwork</label><textarea id="comment_text" name="comment_text" required maxlength="1000" rows="3" placeholder="Share your thoughts..."></textarea><button type="submit" class="mira-action-btn">Post comment</button></form><?php endif; ?>
<div class="mira-comments-list"><h2>All Comments (<?= count($comments) ?><?= count($comments)===100?'+':'' ?>)</h2><?php if (!$comments): ?><p class="mira-no-comments">No comments yet. Be the first to comment!</p><?php endif; ?>
<?php foreach($comments as $comment): ?><article class="mira-comment"><strong><?= miraEsc($comment['FULL_NAME']) ?></strong><p><?= nl2br(miraEsc($comment['comment_text'])) ?></p><small><?= miraEsc(date('M j, Y g:i A',strtotime($comment['created_at']))) ?></small><?php if (!$miraAdminPreview && (int)$comment['user_id']===$uid): ?><form method="post" action="artwork-interactions.php"><input type="hidden" name="csrf_token" value="<?= miraEsc($token) ?>"><input type="hidden" name="artwork_id" value="<?= (int)$id ?>"><input type="hidden" name="comment_id" value="<?= (int)$comment['comment_id'] ?>"><input type="hidden" name="action" value="delete_comment"><button type="submit" class="mira-delete">Delete</button></form><?php endif; ?></article><?php endforeach; ?></div></section><?php endif; ?></main></body></html>
